describe("statistics and option compatibility", () => {
  it("keeps named and default exports equivalent", () => {
    expect(defaultHumanId).toBe(humanId);
  });

  it("supports boolean shorthand and all default word lists", () => {
    jest.spyOn(Math, "random").mockReturnValue(0);
    expect(humanId(false)).toBe(adjectives[0] + nouns[0] + verbs[0]);
    expect(humanId({ separator: "-", capitalize: false, addAdverb: true })).toBe(
      [adjectives[0], nouns[0], verbs[0], adverbs[0]].join("-"),
    );
  });

  it.each([
    [0, false, 14400],
    [1, false, 1080000],
    [2, false, 81000000],
    [2, true, 4779000000],
  ])("counts combinations for %i adjectives with adverb=%s", (adjectiveCount, addAdverb, expected) => {
    expect(poolSize({ adjectiveCount, addAdverb })).toBe(expected);
  });

  it.each([0, 1, 2, 4])("reports attainable length bounds with %i adjectives", (adjectiveCount) => {
    const options = { adjectiveCount, addAdverb: true, separator: "::", capitalize: false };
    const lists = [...Array<string[]>(adjectiveCount).fill(adjectives), nouns, verbs, adverbs];
    // Force the actual shortest/longest word in each list, checking generation against the reported bounds.
    for (const fn of [minLength, maxLength]) {
      const random = jest.spyOn(Math, "random");
      for (const list of lists) {
        const length =
          fn === minLength
            ? Math.min(...list.map((word) => word.length))
            : Math.max(...list.map((word) => word.length));
        random.mockReturnValueOnce((list.findIndex((word) => word.length === length) + 0.5) / list.length);
      }
      expect(humanId(options).length).toBe(fn(options));
      random.mockRestore();
    }
  });

  it.each([-1, 1.5, NaN, Infinity, 2 ** 32])("rejects invalid adjective count %s consistently", (adjectiveCount) => {
    for (const fn of [humanId, poolSize, minLength, maxLength]) {
      expect(() => fn({ adjectiveCount })).toThrow(RangeError);
    }
  });

  it.each([adjectives, nouns, verbs, adverbs])("keeps the word list unique and lowercase", (...words) => {
    expect(new Set(words).size).toBe(words.length);
    for (const word of words) expect(word).toMatch(/^[a-z]+$/);
  });
});
